from math import log
BOLTZMANN_K: float = 1.380649e-23
LN2: float = log(2.0)


def erased_linear_collapse(m: int) -> float:
    """Erasure of collapsing a 2**m-state search to one answer: m bits."""
    return float(m)


def erased_big_collapse(m: int) -> float:
    """Erasure of collapsing a 2**(2**m)-state search to one answer: 2**m bits."""
    return float(2 ** m)


def heat_big_collapse(m: int, T: float = 300.0) -> float:
    """Landauer heat of the big collapse: 2**m * kB * T * ln 2 joules."""
    return erased_big_collapse(m) * BOLTZMANN_K * T * LN2


if __name__ == "__main__":
    for m in range(6):
        print(m, erased_linear_collapse(m), erased_big_collapse(m),
              f"{heat_big_collapse(m):.3e} J")

